PROGRAM PressCell

(* SFC Generated from Visual Editor *)

VAR
    (* Step Active Flags *)
    X_step_idle : BOOL := TRUE; (* Step: IDLE *)
    X_step_feed : BOOL := FALSE; (* Step: FEEDING *)
    X_step_press : BOOL := FALSE; (* Step: PRESSING *)
    X_step_fault : BOOL := FALSE; (* Step: FAULTED *)

    (* Step Elapsed Timers *)
    T_step_idle : TON; (* Timer for IDLE *)
    T_step_feed : TON; (* Timer for FEEDING *)
    T_step_press : TON; (* Timer for PRESSING *)
    T_step_fault : TON; (* Timer for FAULTED *)

    (* Transitions That Fire In This Scan *)
    _F_t_start : BOOL;
    _F_t_fault_feed : BOOL;
    _F_t_feed_done : BOOL;
    _F_t_fault_press : BOOL;
    _F_t_press_done : BOOL;
    _F_t_reset : BOOL;
    (* Transition Conditions, as They Were Evaluated In This Scan *)
    _C_t_start : BOOL;
    _C_t_fault_feed : BOOL;
    _C_t_feed_done : BOOL;
    _C_t_fault_press : BOOL;
    _C_t_press_done : BOOL;
    _C_t_reset : BOOL;

END_VAR

VAR_INPUT
    Start AT %I0.0 : BOOL; (* Start pushbutton *)
    Fault AT %I0.1 : BOOL; (* Fault sensor, TRUE while the fault is present *)
    Reset AT %I0.2 : BOOL; (* Reset pushbutton *)
END_VAR

VAR_OUTPUT
    Feeder AT %Q0.0 : BOOL; (* Feeder *)
    Press AT %Q0.1 : BOOL; (* Press *)
    Alarm AT %Q0.2 : BOOL; (* Alarm lamp *)
END_VAR

(* === Step Timers === *)
T_step_idle(IN := X_step_idle, PT := T#24h);
T_step_feed(IN := X_step_feed, PT := T#24h);
T_step_press(IN := X_step_press, PT := T#24h);
T_step_fault(IN := X_step_fault, PT := T#24h);

(* === Action Execution === *)
(* Action: A_IDLE *)
IF X_step_idle THEN
    Feeder := FALSE; Press := FALSE; Alarm := FALSE;
END_IF;

(* Action: A_FEED *)
IF X_step_feed THEN
    Feeder := TRUE; Press := FALSE; Alarm := FALSE;
END_IF;

(* Action: A_PRESS *)
IF X_step_press THEN
    Feeder := FALSE; Press := TRUE; Alarm := FALSE;
END_IF;

(* Action: A_FAULT *)
IF X_step_fault THEN
    Feeder := FALSE; Press := FALSE; Alarm := TRUE;
END_IF;

(* === Transition Logic === *)
(* Transition: IDLE -> FEEDING *)
_C_t_start := (Start AND NOT Fault);
_F_t_start := X_step_idle AND _C_t_start;
(* Transition: FEEDING -> FAULTED (A fault wins over the timer) *)
_C_t_fault_feed := (Fault);
_F_t_fault_feed := X_step_feed AND _C_t_fault_feed;
(* Transition: PRESSING -> FAULTED (A fault wins over the timer) *)
_C_t_fault_press := (Fault);
_F_t_fault_press := X_step_press AND _C_t_fault_press;
(* Transition: FEEDING -> PRESSING *)
_C_t_feed_done := (T_step_feed.ET >= T#30ms);
_F_t_feed_done := X_step_feed AND _C_t_feed_done AND NOT _F_t_fault_feed;
(* Transition: PRESSING -> IDLE *)
_C_t_press_done := (T_step_press.ET >= T#30ms);
_F_t_press_done := X_step_press AND _C_t_press_done AND NOT _F_t_fault_press;
(* Transition: FAULTED -> IDLE (Reset works only once the fault is gone) *)
_C_t_reset := (Reset AND NOT Fault);
_F_t_reset := X_step_fault AND _C_t_reset;

IF _F_t_start THEN X_step_idle := FALSE; END_IF;
IF _F_t_fault_feed THEN X_step_feed := FALSE; END_IF;
IF _F_t_feed_done THEN X_step_feed := FALSE; END_IF;
IF _F_t_fault_press THEN X_step_press := FALSE; END_IF;
IF _F_t_press_done THEN X_step_press := FALSE; END_IF;
IF _F_t_reset THEN X_step_fault := FALSE; END_IF;
IF _F_t_start THEN X_step_feed := TRUE; END_IF;
IF _F_t_fault_feed THEN X_step_fault := TRUE; END_IF;
IF _F_t_feed_done THEN X_step_press := TRUE; END_IF;
IF _F_t_fault_press THEN X_step_fault := TRUE; END_IF;
IF _F_t_press_done THEN X_step_idle := TRUE; END_IF;
IF _F_t_reset THEN X_step_idle := TRUE; END_IF;

END_PROGRAM

